import type { NextConfig } from "next";

// The portfolio is a single hand-built page (public/index.html) with its own
// Three.js scene, so Next.js only serves it and the media next to it.
const nextConfig: NextConfig = {
  async rewrites() {
    return {
      beforeFiles: [
        { source: "/", destination: "/index.html" },
        // one share page per reel, generated by scripts/build-reel-pages.mjs
        { source: "/work/:id", destination: "/work/:id.html" },
      ],
    };
  },
  async headers() {
    return [
      {
        source: "/videos/:path*",
        headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }],
      },
      {
        source: "/assets/:path*",
        headers: [{ key: "Cache-Control", value: "public, max-age=31536000, immutable" }],
      },
    ];
  },
};

export default nextConfig;
